import 'package:meta/meta.dart';import '../../../../../../Core/Models/product_details_model.dart';import '../../../../../Global/Authentication/data/entities/user_data_model.dart';import '../../data/models/product_preview_entities.dart';@immutableclass HomeStateModel {  final List<ProductPreviewEntities> productsFeatured;  final List<ProductPreviewEntities> productsPopular;  final ProductDetailsModel? productDetails;  final List<ProductPreviewEntities> favoriteProductDetails;  final UserDataModel? userDataModel;  final Map<String, bool> isLoading;  const HomeStateModel({    this.productsFeatured = const [],    this.productsPopular = const [],    this.isLoading = const {},    this.productDetails,    this.userDataModel,    this.favoriteProductDetails = const [],  });  HomeStateModel copyWith({    List<ProductPreviewEntities>? productsFeatured,    List<ProductPreviewEntities>? productsPopular,    Map<String, bool>? isLoading,    ProductDetailsModel? productDetails,    UserDataModel? userDataModel,    List<ProductPreviewEntities>? favoriteProductDetails,  }) {    return HomeStateModel(        productDetails: productDetails ?? this.productDetails,        productsFeatured: productsFeatured ?? this.productsFeatured,        productsPopular: productsPopular ?? this.productsPopular,        isLoading: isLoading ?? this.isLoading,        favoriteProductDetails:        favoriteProductDetails ?? this.favoriteProductDetails,        userDataModel: userDataModel ?? this.userDataModel);  }}